-- Local CI regression coverage. Cloud uses the broader extension-free script.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select no_plan();
select ok(not has_function_privilege('anon','public.leave_quarrel_room(uuid)','EXECUTE'),'Leave requires authenticated role');
select ok(not has_function_privilege('authenticated','quarrel_private.check_room_request(uuid)','EXECUTE'),'Room guard not directly callable');
select ok(not has_table_privilege('authenticated','public.quarrel_players','UPDATE'),'Player detach cannot bypass RPC');
insert into auth.users(id,aud,role,is_anonymous,created_at,updated_at) values
 ('a7777777-7777-4777-8777-777777777777','authenticated','authenticated',true,now(),now()),
 ('b8888888-8888-4888-8888-888888888888','authenticated','authenticated',true,now(),now()),
 ('c9999999-9999-4999-8999-999999999999','authenticated','authenticated',true,now(),now());
create temporary table leave_test(kind text primary key, snapshot jsonb);
grant select,insert,update on leave_test to authenticated;
set local role authenticated;
set local request.headers='{}';
set local request.jwt.claim.sub='a7777777-7777-4777-8777-777777777777';
insert into leave_test values('old',public.create_quarrel_room('Original host'));
select public.set_quarrel_ready(true);
set local request.jwt.claim.sub='b8888888-8888-4888-8888-888888888888';
select public.join_quarrel_room((select snapshot->>'code' from leave_test where kind='old'),'Original guest');
select public.set_quarrel_ready(true);
set local request.jwt.claim.sub='a7777777-7777-4777-8777-777777777777';
select throws_ok($$select public.leave_quarrel_room(gen_random_uuid())$$,'P0001','STALE_ROOM','Wrong expected room cannot detach current seat');
select throws_ok($$select public.leave_quarrel_room(null)$$,'P0001','STALE_ROOM','Missing expected room rejected');
select is(public.leave_quarrel_room((select (snapshot->>'id')::uuid from leave_test where kind='old')),null::jsonb,'Leave returns no current room');
select is(public.leave_quarrel_room((select (snapshot->>'id')::uuid from leave_test where kind='old')),null::jsonb,'Leave retry before next room is idempotent');
select is(public.get_quarrel_room(),null::jsonb,'Saved old room no longer resumes');
select is((select count(*)::integer from public.quarrel_rooms),0,'Departed member cannot read old room through RLS');
select is((select count(*)::integer from public.quarrel_players),0,'Departed member cannot read old players through RLS');
insert into leave_test values('new',public.create_quarrel_room('New host'));
select isnt((select snapshot->>'id' from leave_test where kind='new'),(select snapshot->>'id' from leave_test where kind='old'),'Same identity creates a different room');
select is((select snapshot->>'you' from leave_test where kind='new'),'A','Fresh room assigns host slot');
select is((select snapshot #>> '{players,0,name}' from leave_test where kind='new'),'New host','Fresh display name independent of old record');
select is((select snapshot #>> '{debate,phase}' from leave_test where kind='new'),'setup','Fresh debate starts in setup');
select throws_ok($$select public.leave_quarrel_room((select (snapshot->>'id')::uuid from leave_test where kind='old'))$$,'P0001','STALE_ROOM','Delayed leave cannot detach new room');
select set_config('request.headers',jsonb_build_object('x-quarrel-room-id',(select snapshot->>'id' from leave_test where kind='old'))::text,true);
select throws_ok($$select public.set_quarrel_ready(true)$$,'P0001','STALE_ROOM','Stale readiness rejected under lock');
select throws_ok($$select public.set_quarrel_theme('courtroom')$$,'P0001','STALE_ROOM','Stale theme rejected under lock');
select throws_ok($$select public.heartbeat_quarrel_room()$$,'P0001','STALE_ROOM','Stale heartbeat cannot update new room');
select throws_ok($$select public.propose_quarrel_debate('Old topic','Old A','Old B',0)$$,'P0001','STALE_ROOM','Stale topic rejected');
select throws_ok($$select public.submit_quarrel_argument('Old argument',1,0)$$,'P0001','STALE_ROOM','Stale official argument rejected');
select set_config('request.headers',jsonb_build_object('x-quarrel-room-id',(select snapshot->>'id' from leave_test where kind='new'))::text,true);
select is(public.set_quarrel_theme('detective')->>'themeId','detective','Correct room header allows authorized change');
select is(public.get_quarrel_room() #>> '{players,0,ready}','false','Rejected old readiness did not mutate new room');
set local request.headers='{}';
set local request.jwt.claim.sub='b8888888-8888-4888-8888-888888888888';
update leave_test set snapshot=public.get_quarrel_room() where kind='old';
select is((select snapshot #>> '{players,0,name}' from leave_test where kind='old'),'Original host','Remaining peer retains old name');
select is((select snapshot #>> '{players,0,connected}' from leave_test where kind='old'),'false','Departure immediately disconnects');
select is((select snapshot #>> '{players,0,ready}' from leave_test where kind='old'),'false','Departure clears readiness');
select is((select jsonb_array_length(snapshot->'players') from leave_test where kind='old'),2,'Historical slot is retained');
select is(public.join_quarrel_room((select snapshot->>'code' from leave_test where kind='old'),'Original guest')->>'id',(select snapshot->>'id' from leave_test where kind='old'),'Existing peer can recover closed room');
set local request.jwt.claim.sub='c9999999-9999-4999-8999-999999999999';
select is(public.leave_quarrel_room((select (snapshot->>'id')::uuid from leave_test where kind='old')),null::jsonb,'Unseated outsider cannot affect room');
select throws_ok($$select public.join_quarrel_room((select snapshot->>'code' from leave_test where kind='old'),'Replacement')$$,'P0001','ROOM_CLOSED','Departed slot cannot be replaced');
select is(public.get_quarrel_room(),null::jsonb,'Rejected outsider still has no room');
insert into leave_test values('other',public.create_quarrel_room('Other host'));
select throws_ok($$select public.leave_quarrel_room((select (snapshot->>'id')::uuid from leave_test where kind='old'))$$,'P0001','STALE_ROOM','Seated outsider cannot leave another room');
set local request.jwt.claim.sub='a7777777-7777-4777-8777-777777777777';
select public.leave_quarrel_room((select (snapshot->>'id')::uuid from leave_test where kind='new'));
select is(public.join_quarrel_room((select snapshot->>'code' from leave_test where kind='other'),'Joining host')->>'you','B','Same identity can join after leaving');
select is((select count(*)::integer from public.quarrel_players where user_id=auth.uid()),1,'Exactly one current identity membership');
select public.leave_quarrel_room((select (snapshot->>'id')::uuid from leave_test where kind='other'));
set local request.jwt.claim.sub='c9999999-9999-4999-8999-999999999999';
select is(public.get_quarrel_room() #>> '{players,1,name}','Joining host','Guest departure preserves name');
select is(public.get_quarrel_room() #>> '{players,1,connected}','false','Guest departure immediately visible');
reset role;
select is((select count(*)::integer from public.quarrel_players where user_id is null and room_id in (select (snapshot->>'id')::uuid from leave_test)),3,'All departed seats remain as records');
select * from finish();
rollback;
